const assert=require('node:assert/strict'),H=require('./roster-model');let n=0;
const test=(name,fn)=>{fn();n++;console.log('PASS '+name)};
test('新赛事为空名单，不能直接开桌',()=>{const t=H.makeEmptyTournament('n','n','team');assert.equal(t.players.length,0);assert.equal(t.teams.length,0);assert.throws(()=>H.newMatch(t),/四名/)});
test('录入队伍与四名选手后可开桌',()=>{const t=H.makeEmptyTournament('n','n','team');const team=H.saveTeam(t,{name:'青岚',short:'青',color:'#155e49'});for(let i=0;i<4;i++)H.savePlayer(t,{name:'选手'+i,number:'P'+i,teamId:team.id});const m=H.newMatch(t);assert.equal(m.seats.length,4);assert.ok(m.seats.every(s=>s.teamId===team.id));assert.equal(H.scoreMatch(m,t).length,4)});
test('赛事编号唯一，同名允许不同编号',()=>{const t=H.makeEmptyTournament('n','n','individual');H.savePlayer(t,{name:'张三',number:'001'});H.savePlayer(t,{name:'张三',number:'002'});assert.throws(()=>H.savePlayer(t,{name:'李四',number:'001'}),/已使用/)});
test('跨赛事队伍归属被拒绝',()=>{const a=H.makeEmptyTournament('a','a','team'),b=H.makeEmptyTournament('b','b','team');const team=H.saveTeam(a,{name:'队伍'});assert.throws(()=>H.savePlayer(b,{name:'选手',number:'01',teamId:team.id}),/不属于/)});
test('换队不修改已发布贡献',()=>{const [t]=H.seed(),p=t.players[0],old=p.teamId,oldTotal=H.leaderboard(t,'all','team').find(r=>r.id===old).total;const team=H.saveTeam(t,{name:'新队'});H.savePlayer(t,{name:p.name,number:'001',teamId:team.id},p.id);assert.equal(H.leaderboard(t,'all','team').find(r=>r.id===old).total,oldTotal);assert.equal(H.leaderboard(t,'all','team').find(r=>r.id===team.id).total,0);assert.equal(H.teamContributions(t,old,'all').find(r=>r.id===p.id).current,false)});
test('停用及待分配选手不进入新阵容',()=>{const t=H.makeTournament('n','n','team');t.players[0].active=false;assert.throws(()=>H.newMatch(t),/四名/);t.players[0].active=true;delete t.players[0].teamId;assert.throws(()=>H.newMatch(t),/四名/)});
test('同场阵容拒绝重复，新人加入重置点数',()=>{const t=H.makeTournament('n','n','individual'),m=H.newMatch(t);assert.throws(()=>H.setLineup(t,m,Array(4).fill(t.players[0].id)),/不同/);const p=H.savePlayer(t,{name:'新人',number:'NEW'});const r=H.setLineup(t,m,[p.id,...t.players.slice(1,4).map(p=>p.id)]);assert.equal(r.resetScores,true);assert.ok(m.seats.every(s=>s.score===25000))});
test('更换座次，分数随本人保留',()=>{const t=H.makeTournament('n','n','individual'),m=H.newMatch(t);const original=m.seats.map(s=>({...s}));H.setLineup(t,m,[...original].reverse().map(s=>s.playerId));assert.deepEqual(m.seats.map(s=>s.score),original.reverse().map(s=>s.score))});
test('有事件的被换下选手须先处理事件',()=>{const t=H.makeTournament('n','n','individual'),m=H.newMatch(t);m.penalties.push({playerId:t.players[0].id,amount:100,scope:'personal',reason:'测试'});const p=H.savePlayer(t,{name:'新人',number:'NEW'});assert.throws(()=>H.setLineup(t,m,[p.id,...t.players.slice(1,4).map(p=>p.id)]),/仍有/)});
test('统计普通对局的均顺与比率',()=>{const t=H.makeTournament('n','n','individual'),m=H.newMatch(t);H.publish(t,m);const r=H.statistics(t,'all','player')[0];assert.equal(r.avgRank,1);assert.equal(r.topRate,1);assert.equal(r.topTwo,1);assert.equal(r.avoidLast,1);assert.equal(r.best,41600)});
test('同点均分次数，四人同点平均顺位为2.5',()=>{const t=H.makeTournament('n','n','individual'),m=H.newMatch(t);m.seats.forEach(s=>s.score=25000);H.publish(t,m);H.statistics(t,'all','player').forEach(r=>{assert.deepEqual(r.places,[.25,.25,.25,.25]);assert.equal(r.avgRank,2.5);assert.equal(r.topRate,.25);assert.equal(r.topTwo,.5);assert.equal(r.avoidLast,.75)})});
test('零场选手不捏造比率与最高点数',()=>{const t=H.makeTournament('n','n','individual');H.statistics(t,'all','player').forEach(r=>{assert.equal(r.avgRank,null);assert.equal(r.topRate,null);assert.equal(r.best,null)})});
test('成员贡献合计等于队伍原始净分',()=>{const [t]=H.seed();H.leaderboard(t,'all','team').forEach(r=>assert.equal(H.teamContributions(t,r.id,'all').reduce((n,p)=>n+p.total,0),r.raw))});
test('换人重置点数时也清空旧供托',()=>{const t=H.makeTournament('n','n','individual','npm'),m=H.newMatch(t);m.deposit=1000;m.seats[0].score-=1000;const p=H.savePlayer(t,{name:'新人',number:'NEW'});H.setLineup(t,m,[p.id,...t.players.slice(1,4).map(p=>p.id)]);assert.equal(m.deposit,0);assert.equal(H.scoreMatch(m,t).reduce((sum,r)=>sum+r.net,0),0)});
console.log(n+' roster/statistics cases passed');
